import { Text } from '@/uikit';
import { useTranslation } from 'react-i18next';
import { NavLink } from 'react-router-dom';
import styles from './Navbar.module.scss';

export function Navbar() {
    const [t] = useTranslation();
    return (
        <div className={styles.root}>
            <NavLink
                to='/'
                className={({ isActive }) =>
                    [styles.item, isActive && styles.active]
                        .filter(Boolean)
                        .join(' ')
                }
            >
                <div className={styles.itemIcon}><Cards /></div>
                <Text
                    weight='semibold'
                    align='center'
                    className={styles.itemText}
                >{t('Cards')}</Text>
            </NavLink>
            <NavLink
                to='/payment/transfer'
                className={({ isActive }) =>
                    [styles.item, isActive && styles.active]
                        .filter(Boolean)
                        .join(' ')
                }
            >
                <div className={styles.itemIcon}><Transfer /></div>
                <Text
                    align='center'
                    weight='semibold'
                    className={styles.itemText}
                >{t('Transfers')}</Text>
            </NavLink>
            <NavLink
                to='/payment/qr'
                className={({ isActive }) =>
                    [styles.item, isActive && styles.active]
                        .filter(Boolean)
                        .join(' ')
                }
            >
                <div className={styles.itemIcon}><Qr /></div>
                <Text
                    align='center'
                    weight='semibold'
                    className={styles.itemText}
                >{t('QR Payment')}</Text>
            </NavLink>
        </div>
    );
}

